/* AUTOGENERATED-LIKE UNITY TEST FILE FOR GPADC */

#include "unity.h"
#include <setjmp.h>
#include <stdio.h>
#include <string.h>
#include <stdbool.h>

#include "Driver_GPADC.h"
#include "arcs_ap.h"

static void *gpadc_handle = NULL;
static volatile uint32_t gpadc_event = 0;

static void gpadc_complete_cb(uint32_t event, void *param)
{
    (void)param;
    gpadc_event |= event;
}

/* Forward declarations for newly added tests (GPIO-style concise naming) */
void test_gpadc_interrupt_complete_verify(void);
void test_gpadc_fifo_full_vbat_verify(void);

static void assert_adc_value_valid(uint32_t channel_sel)
{
    uint32_t adc_value = HAL_GPADC_GetValue(gpadc_handle, channel_sel);
    TEST_ASSERT_LESS_OR_EQUAL_UINT16(1024, adc_value);
    TEST_ASSERT_GREATER_OR_EQUAL_UINT16(0, adc_value);
    TEST_ASSERT_NOT_EQUAL(0xFFFF, adc_value);
}

static bool wait_for_event(uint32_t mask, uint32_t loops)
{
    while (loops--) {
        if (gpadc_event & mask) {
            return true;
        }
    }
    return false;
}

void setUp(void)
{
    gpadc_handle = GPADC();
    /* Ensure global interrupt enabled for IT/FIFO callbacks in CI */
    enable_GINT();
}

void tearDown(void)
{
    if (gpadc_handle) {
        HAL_GPADC_Uninitialize(gpadc_handle);
    }
}

void test_gpadc_pointer_verify(void)
{
    TEST_ASSERT_NOT_NULL(gpadc_handle);
}

void test_gpadc_polling_multi_channels_values_verify(void)
{
    TEST_ASSERT_EQUAL(CSK_DRIVER_OK, HAL_GPADC_Initialize(gpadc_handle));

    /* enable channels: 0/1/2/vbat, disable dma */
    TEST_ASSERT_EQUAL(CSK_DRIVER_OK, HAL_GPADC_Control(gpadc_handle,
        (CSK_GPADC_CHANNEL_SEL_0 |
         CSK_GPADC_CHANNEL_SEL_1 |
         CSK_GPADC_CHANNEL_SEL_2 |
         CSK_GPADC_CHANNEL_SEL_VBAT) |
        CSK_GPADC_DMA_ENABLE(0)));

    /* vref/triggers per demo */
    TEST_ASSERT_EQUAL(CSK_DRIVER_OK, HAL_GPADC_SetVrefSel(gpadc_handle, 0));
    TEST_ASSERT_EQUAL(CSK_DRIVER_OK, HAL_GPADC_SetTriggerNum(gpadc_handle, 2));

    TEST_ASSERT_EQUAL(CSK_DRIVER_OK, HAL_GPADC_Start(gpadc_handle));
    TEST_ASSERT_EQUAL(CSK_DRIVER_OK, HAL_GPADC_PollForConversion(gpadc_handle, 0));

    assert_adc_value_valid(CSK_GPADC_CHANNEL_SEL_0);
    assert_adc_value_valid(CSK_GPADC_CHANNEL_SEL_1);
    assert_adc_value_valid(CSK_GPADC_CHANNEL_SEL_2);
    assert_adc_value_valid(CSK_GPADC_CHANNEL_SEL_VBAT);
}

int main(void)
{
    UnityBegin("test/driver/gpadc/test_gpadc.c");
    RUN_TEST(test_gpadc_pointer_verify, __LINE__);
    RUN_TEST(test_gpadc_polling_multi_channels_values_verify, __LINE__);
    RUN_TEST(test_gpadc_interrupt_complete_verify, __LINE__);
    RUN_TEST(test_gpadc_fifo_full_vbat_verify, __LINE__);
    return (UnityEnd());
}

void test_gpadc_interrupt_complete_verify(void)
{
    /* interrupt complete */
    gpadc_event = 0;
    TEST_ASSERT_EQUAL(CSK_DRIVER_OK, HAL_GPADC_Initialize(gpadc_handle));
    TEST_ASSERT_EQUAL(CSK_DRIVER_OK, HAL_GPADC_Control(gpadc_handle,
        (CSK_GPADC_CHANNEL_SEL_0 |
         CSK_GPADC_CHANNEL_SEL_1 |
         CSK_GPADC_CHANNEL_SEL_2 |
         CSK_GPADC_CHANNEL_SEL_VBAT) |
        CSK_GPADC_DMA_ENABLE(0)));
    TEST_ASSERT_EQUAL(CSK_DRIVER_OK, HAL_GPADC_SetVrefSel(gpadc_handle, 0));
    TEST_ASSERT_EQUAL(CSK_DRIVER_OK, HAL_GPADC_SetTriggerNum(gpadc_handle, 1));
    HAL_GPADC_RegisterCompleteCallback(gpadc_handle, gpadc_complete_cb);
    TEST_ASSERT_EQUAL(CSK_DRIVER_OK, HAL_GPADC_Start_IT(gpadc_handle));

    TEST_ASSERT_TRUE_MESSAGE(wait_for_event(CSK_GPADC_COMPLETE, 2000000), "gpadc complete timeout");
}

static void gpadc_fifo_cb(uint32_t event, void *param)
{
    (void)param;
    gpadc_event |= event;
}

void test_gpadc_fifo_full_vbat_verify(void)
{
    /* fifo full (vbat) */
    gpadc_event = 0;
    TEST_ASSERT_EQUAL(CSK_DRIVER_OK, HAL_GPADC_Initialize(gpadc_handle));
    TEST_ASSERT_EQUAL(CSK_DRIVER_OK, HAL_GPADC_Control(gpadc_handle,
        CSK_GPADC_CHANNEL_SEL_VBAT | CSK_GPADC_DMA_ENABLE(0)));
    TEST_ASSERT_EQUAL(CSK_DRIVER_OK, HAL_GPADC_SetVrefSel(gpadc_handle, 0));
    TEST_ASSERT_EQUAL(CSK_DRIVER_OK, HAL_GPADC_SetTriggerNum(gpadc_handle, 16));
    HAL_GPADC_EnableFifoInterrupt(gpadc_handle, CSK_GPADC_VBAT, CSK_GPADC_FIFO_FULL);
    HAL_GPADC_RegisterChannelCallback(gpadc_handle, CSK_GPADC_VBAT, gpadc_fifo_cb);
    /* accept complete as fallback */
    HAL_GPADC_RegisterCompleteCallback(gpadc_handle, gpadc_complete_cb);
    TEST_ASSERT_EQUAL(CSK_DRIVER_OK, HAL_GPADC_Start(gpadc_handle));

    TEST_ASSERT_TRUE_MESSAGE(wait_for_event(CSK_GPADC_FIFO_FULL | CSK_GPADC_COMPLETE, 2000000), "gpadc fifo full/complete timeout");
}